(6950026, 1046743, 124815, '<td valign="top">Reminds me of <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21_F.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21_F.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21_F.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=114285" rel="nofollow" target="_blank">neat</a> painterly exercises. I like the flatness of this still life without the darkened edges</td>', 'Reminds me of  neat painterly exercises. I like the flatness of this still life without the darkened edges', '2013-01-05 21:18:36.000000', NULL, 1),
