(6950033, 1046130, 124815, '<td valign="top">It should be dreamy but actually it is not. Perhaps on a grey sky?</td>', 'It should be dreamy but actually it is not. Perhaps on a grey sky?', '2013-01-05 21:25:32.000000', NULL, 1),
(6950136, 1046745, 30049, '<td valign="top">I really like this scene and the B&amp;W choice works well.  Only nit I have is the tonal range seems tight, and somewhat lacking at the high end.</td>', 'I really like this scene and the B&W choice works well.  Only nit I have is the tonal range seems tight, and somewhat lacking at the high end.', '2013-01-05 23:45:39.000000', NULL, 1),
(6950137, 1046097, 30049, '<td valign="top">Horizon is crooked.  A little burning inside the windmill to knock down the halo (HDR or Tonemapping effect?) would eliminate the competition for attention and let that sky really jump out.<br/> <br/>BTW - I was just kidding about the horizon.  Figured you probably checked that a couple of times.  :-)</td>', 'Horizon is crooked.  A little burning inside the windmill to knock down the halo (HDR or Tonemapping effect?) would eliminate the competition for attention and let that sky really jump out. BTW - I was just kidding about the horizon.  Figured you probably checked that a couple of times.  :-)', '2013-01-05 23:49:48.000000', NULL, 1),
(6950139, 1046775, 30049, '<td valign="top">Lovely scene - good job controlling whites.</td>', 'Lovely scene - good job controlling whites.', '2013-01-05 23:52:28.000000', NULL, 1),
(6950143, 1045236, 30049, '<td valign="top">Great find and wonderful processing!</td>', 'Great find and wonderful processing!', '2013-01-05 23:53:59.000000', NULL, 1),
