(6950292, 1047351, 30712, '<td valign="top">Beautifully done.  The depth of field is spot on.</td>', 'Beautifully done.  The depth of field is spot on.', '2013-01-06 08:47:26.000000', NULL, 1),
(6950315, 1047275, 100393, '<td valign="top">I''m going through the entries, stopping at those images I feel have had the benefit of an unconventional eye and dwelling a little longer to try to see and appreciate what you saw. This is one of those images. <br/> <br/>Positives: Great mood you''ve captured here and you''re right - this is suggestive of an old scene - your coloration seems in keeping too, though of course his ear-gear is a little anachronistic. I actually think that adds to it though - it convinces that this isn''t a themed place or a living museum but something you''ve happened upon and interpreted. I like that.<br/> <br/>Critical stuff: Nope<br/> <br/>Overall: A delightful candid.</td>', 'I''m going through the entries, stopping at those images I feel have had the benefit of an unconventional eye and dwelling a little longer to try to see and appreciate what you saw. This is one of those images.  Positives: Great mood you''ve captured here and you''re right - this is suggestive of an old scene - your coloration seems in keeping too, though of course his ear-gear is a little anachronistic. I actually think that adds to it though - it convinces that this isn''t a themed place or a living museum but something you''ve happened upon and interpreted. I like that. Critical stuff: Nope Overall: A delightful candid.', '2013-01-06 09:08:08.000000', NULL, 1),
(6950316, 1047325, 30712, '<td valign="top">These birds can supply amazing photo opportunities.  Having said that, this is brilliant.  I love the lighting and wonderful curves.</td>', 'These birds can supply amazing photo opportunities.  Having said that, this is brilliant.  I love the lighting and wonderful curves.', '2013-01-06 09:09:13.000000', NULL, 1),
(6950317, 1047340, 30712, '<td valign="top">A moody intense image.  As in all good pictures this one tells so many stories.</td>', 'A moody intense image.  As in all good pictures this one tells so many stories.', '2013-01-06 09:10:09.000000', NULL, 1),
(6950319, 1047069, 30712, '<td valign="top">The lighting makes this image.  The yellow light adds interest where it is needed most.</td>', 'The lighting makes this image.  The yellow light adds interest where it is needed most.', '2013-01-06 09:11:13.000000', NULL, 1),
(6950320, 1047305, 100393, '<td valign="top">I''m going through the entries, stopping at those images I feel have had the benefit of an unconventional eye and dwelling a little longer to try to see and appreciate what you saw. This is one of those images. <br/> <br/>Positives: Good overall exposure handling here in what looks like tricky light to me. The people are perfectly rendered, yet we still easily discern the door and the tree shadow. The juxtaposition of the people and the pigeons - both going about their business, works really well.<br/> <br/>Critical stuff: Although you''ve pitched the exposure perfectly, I''d have made some local adjustments in post - I''d have brought the highlights of the wall back and darkened the shadow of the tree for a bit of additional drama. (Though I''m presuming you shot in RAW - you may not have had the dynamic range to do that if you shot in JPEG).<br/> <br/>Overall: A fine and engaging shot.</td>', 'I''m going through the entries, stopping at those images I feel have had the benefit of an unconventional eye and dwelling a little longer to try to see and appreciate what you saw. This is one of those images.  Positives: Good overall exposure handling here in what looks like tricky light to me. The people are perfectly rendered, yet we still easily discern the door and the tree shadow. The juxtaposition of the people and the pigeons - both going about their business, works really well. Critical stuff: Although you''ve pitched the exposure perfectly, I''d have made some local adjustments in post - I''d have brought the highlights of the wall back and darkened the shadow of the tree for a bit of additional drama. (Though I''m presuming you shot in RAW - you may not have had the dynamic range to do that if you shot in JPEG). Overall: A fine and engaging shot.', '2013-01-06 09:12:24.000000', NULL, 1),
(6950321, 1046785, 30712, '<td valign="top">This has an almost other worldly feel to it.  Lovely light and the shape of the bird caught on the diagonal is fantastic.</td>', 'This has an almost other worldly feel to it.  Lovely light and the shape of the bird caught on the diagonal is fantastic.', '2013-01-06 09:12:44.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6950322, 1047324, 30712, '<td valign="top">Unfortunately I''m not into modern art to this extent.  I evaluate pictures based on whether I would like to live with them over a period of time.  I''d just like more to keep my attention for longer.  Others I am sure will love your work.</td>', 'Unfortunately I''m not into modern art to this extent.  I evaluate pictures based on whether I would like to live with them over a period of time.  I''d just like more to keep my attention for longer.  Others I am sure will love your work.', '2013-01-06 09:15:49.000000', NULL, 1),
(6950324, 1047058, 30712, '<td valign="top">A nice idea but I''d like the toy to have rather more personality so that I can identify with its predicament.</td>', 'A nice idea but I''d like the toy to have rather more personality so that I can identify with its predicament.', '2013-01-06 09:17:08.000000', NULL, 1),
(6950325, 1046070, 100393, '<td valign="top">I''m going through the entries, stopping at those images I feel have had the benefit of an unconventional eye and dwelling a little longer to try to see and appreciate what you saw. This is one of those images. <br/> <br/>Positives: This looks to live somewhere between a <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21_N.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21_N.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21_N.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=54645" rel="nofollow" target="_blank">bspurgeon</a> and a <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21_N.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21_N.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21_N.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=50641" rel="nofollow" target="_blank">skewsme</a> - a pretty good photographic place to be! I really like the way you have captured both detail and glow here. <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21_N.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21_N.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21_N.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=113156" rel="nofollow" target="_blank">jagar</a> manages that in his street shots and I always like how it looks. This technique really emphasises texture and light and gives the image a well defined artistic identity.<br/> <br/>Critical stuff: I''m not keen on the border - it constrains the image and given the grey of the branches - I''d quite enjoy seeing it merge into the DPC grey (the default 1px border aside)<br/> <br/>Overall: An image that is true to itself and good at being so!</td>', 'I''m going through the entries, stopping at those images I feel have had the benefit of an unconventional eye and dwelling a little longer to try to see and appreciate what you saw. This is one of those images.  Positives: This looks to live somewhere between a  bspurgeon and a  skewsme - a pretty good photographic place to be! I really like the way you have captured both detail and glow here.  jagar manages that in his street shots and I always like how it looks. This technique really emphasises texture and light and gives the image a well defined artistic identity. Critical stuff: I''m not keen on the border - it constrains the image and given the grey of the branches - I''d quite enjoy seeing it merge into the DPC grey (the default 1px border aside) Overall: An image that is true to itself and good at being so!', '2013-01-06 09:18:22.000000', NULL, 1),
(6950326, 1047346, 30712, '<td valign="top">For me the blur is overdone to the extent that it looks like a mistake rather than intentional.  A sharp image of the cat with a very limited depth of field would do the trick for me.</td>', 'For me the blur is overdone to the extent that it looks like a mistake rather than intentional.  A sharp image of the cat with a very limited depth of field would do the trick for me.', '2013-01-06 09:18:59.000000', NULL, 1),
(6950328, 1046863, 30712, '<td valign="top">Fireworks can be spectacular but here the tilt of the water and bursts of light lined up with each other, don''t make for sufficient interest.</td>', 'Fireworks can be spectacular but here the tilt of the water and bursts of light lined up with each other, don''t make for sufficient interest.', '2013-01-06 09:20:57.000000', NULL, 1),
(6950329, 1045195, 100393, '<td valign="top">I''m going through the entries, stopping at those images I feel have had the benefit of an unconventional eye and dwelling a little longer to try to see and appreciate what you saw. This is one of those images. <br/> <br/>Positives: Colour-wise, I''m a sucker for these (getting cliched) retro looks, I''ll enjoy them long after they go back out of fashion. What makes this effective is how well matched to the scene it is - this image is meant to have this coloration! Subject-wise, I like the ''everydayness'' the communication of a chill in the air and the partial sharpness. The contre-jour technique and long shadows are effective too.<br/> <br/>Critical stuff: Not really<br/> <br/>Overall: A very enjoyable image.</td>', 'I''m going through the entries, stopping at those images I feel have had the benefit of an unconventional eye and dwelling a little longer to try to see and appreciate what you saw. This is one of those images.  Positives: Colour-wise, I''m a sucker for these (getting cliched) retro looks, I''ll enjoy them long after they go back out of fashion. What makes this effective is how well matched to the scene it is - this image is meant to have this coloration! Subject-wise, I like the ''everydayness'' the communication of a chill in the air and the partial sharpness. The contre-jour technique and long shadows are effective too. Critical stuff: Not really Overall: A very enjoyable image.', '2013-01-06 09:22:23.000000', NULL, 1),
(6950330, 1045581, 30712, '<td valign="top">I love moody shots but here there is a lack of magic.  Magic is difficult to quantify I''m afraid so I can''t quite explain how to lift this image into a different plane.</td>', 'I love moody shots but here there is a lack of magic.  Magic is difficult to quantify I''m afraid so I can''t quite explain how to lift this image into a different plane.', '2013-01-06 09:23:54.000000', NULL, 1),
(6950332, 1046445, 30712, '<td valign="top">This idea does inspire in terms of its concept.  Unfortunately this particular image does not project the idea to me in an exciting or interesting way.</td>', 'This idea does inspire in terms of its concept.  Unfortunately this particular image does not project the idea to me in an exciting or interesting way.', '2013-01-06 09:26:52.000000', NULL, 1),
(6950333, 1046444, 100393, '<td valign="top">I''m going through the entries, stopping at those images I feel have had the benefit of an unconventional eye and dwelling a little longer to try to see and appreciate what you saw. This is one of those images. <br/> <br/>Positives: Superbly seen, composed and exposed. If this is a candid, I''m in awe. If it isn''t then I''m impressed that I''m not completely convinced that it isn''t! The way the image is broken into two halves - the lift and the stairs - and the way each half is itself beautifully exposed (despite the massively different lighting) and composed is remarkable. More impressive still that this two (quite discrete) halves hang together so well.<br/> <br/>Critical stuff: I do wish the structure on the left border of the image had been removed...<br/> <br/>Overall: Magnificent work.</td>', 'I''m going through the entries, stopping at those images I feel have had the benefit of an unconventional eye and dwelling a little longer to try to see and appreciate what you saw. This is one of those images.  Positives: Superbly seen, composed and exposed. If this is a candid, I''m in awe. If it isn''t then I''m impressed that I''m not completely convinced that it isn''t! The way the image is broken into two halves - the lift and the stairs - and the way each half is itself beautifully exposed (despite the massively different lighting) and composed is remarkable. More impressive still that this two (quite discrete) halves hang together so well. Critical stuff: I do wish the structure on the left border of the image had been removed... Overall: Magnificent work.', '2013-01-06 09:26:54.000000', NULL, 1),
(6950334, 1047367, 64446, '<td valign="top">What a catch!  Alas you couldn''t go beyond the fence. I''d try cropping the structure at right though.</td>', 'What a catch!  Alas you couldn''t go beyond the fence. I''d try cropping the structure at right though.', '2013-01-06 09:27:55.000000', NULL, 1),
(6950335, 1046883, 100393, '<td valign="top">I''m going through the entries, stopping at those images I feel have had the benefit of an unconventional eye and dwelling a little longer to try to see and appreciate what you saw. This is one of those images. <br/> <br/>Positives: Way to us a POV to good effect! Superb (almost magic trick) composition with the zones of population peppering the image. Your title is good too - reinforcing the sense of discrete zones. Excellent toning - I particularly like the ''wave'' of black bottom centre.<br/> <br/>Critical stuff: Nope.<br/> <br/>Overall: Superb scene, superbly seen.</td>', 'I''m going through the entries, stopping at those images I feel have had the benefit of an unconventional eye and dwelling a little longer to try to see and appreciate what you saw. This is one of those images.  Positives: Way to us a POV to good effect! Superb (almost magic trick) composition with the zones of population peppering the image. Your title is good too - reinforcing the sense of discrete zones. Excellent toning - I particularly like the ''wave'' of black bottom centre. Critical stuff: Nope. Overall: Superb scene, superbly seen.', '2013-01-06 09:29:30.000000', NULL, 1),
(6950336, 1047211, 64446, '<td valign="top">Nice POV!</td>', 'Nice POV!', '2013-01-06 09:30:03.000000', NULL, 1),
(6950337, 1047303, 64446, '<td valign="top">Engaging...</td>', 'Engaging...', '2013-01-06 09:31:18.000000', NULL, 1),
(6950340, 1046166, 100393, '<td valign="top">I''m going through the entries, stopping at those images I feel have had the benefit of an unconventional eye and dwelling a little longer to try to see and appreciate what you saw. This is one of those images. <br/> <br/>Positives: You have captured a lovely sense of casual candidness here - it has a really relaxed feeling about it. Much of this sense of calm is due to your lovely coloration. I certainly want to know more about the people - you''ve managed not to lose them in the photographic trickery of reflection and leading lines. There''s a danger such a precise composition would make the image ''of the image'' rather than ''of the people'' but you''ve avoid that through a great sense of balance.<br/> <br/>Critical stuff. Nope<br/> <br/>Overall: Masterful group portrait.</td>', 'I''m going through the entries, stopping at those images I feel have had the benefit of an unconventional eye and dwelling a little longer to try to see and appreciate what you saw. This is one of those images.  Positives: You have captured a lovely sense of casual candidness here - it has a really relaxed feeling about it. Much of this sense of calm is due to your lovely coloration. I certainly want to know more about the people - you''ve managed not to lose them in the photographic trickery of reflection and leading lines. There''s a danger such a precise composition would make the image ''of the image'' rather than ''of the people'' but you''ve avoid that through a great sense of balance. Critical stuff. Nope Overall: Masterful group portrait.', '2013-01-06 09:37:24.000000', NULL, 1),
(6950341, 1047302, 64446, '<td valign="top">Love the span... great job on getting a sharp focus on its face!</td>', 'Love the span... great job on getting a sharp focus on its face!', '2013-01-06 09:37:25.000000', NULL, 1),
(6950342, 1047380, 64446, '<td valign="top">Very poised, great capture!</td>', 'Very poised, great capture!', '2013-01-06 09:38:27.000000', NULL, 1),
(6950344, 1047216, 64446, '<td valign="top">Interesting idea, sharp focus, works well with black bg.</td>', 'Interesting idea, sharp focus, works well with black bg.', '2013-01-06 09:40:54.000000', NULL, 1),
(6950345, 1047346, 100393, '<td valign="top">I''m going through the entries, stopping at those images I feel have had the benefit of an unconventional eye and dwelling a little longer to try to see and appreciate what you saw. This is one of those images. <br/> <br/>Positives: A Lensbaby cat! As someone well versed in dissolving the legs of my own pets in blurry goodness, I like what you are doing here. I particularly like the way the cat is peering down as if eyeing with suspicion the diminishing clarity of the environment underneath. Lovely ones too and through the use of the curtain, a resonance with the work of <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21_F.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21_F.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21_F.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=35804" rel="nofollow" target="_blank">RKT</a>. As a self-confessed groupie of her work - that''s always a good thing in my eye.<br/> <br/>Critical stuff: Nope<br/> <br/>Overall: Lovely stuff.</td>', 'I''m going through the entries, stopping at those images I feel have had the benefit of an unconventional eye and dwelling a little longer to try to see and appreciate what you saw. This is one of those images.  Positives: A Lensbaby cat! As someone well versed in dissolving the legs of my own pets in blurry goodness, I like what you are doing here. I particularly like the way the cat is peering down as if eyeing with suspicion the diminishing clarity of the environment underneath. Lovely ones too and through the use of the curtain, a resonance with the work of  RKT. As a self-confessed groupie of her work - that''s always a good thing in my eye. Critical stuff: Nope Overall: Lovely stuff.', '2013-01-06 09:41:34.000000', NULL, 1),
(6950346, 1047325, 64446, '<td valign="top">Lovely textures and color!!</td>', 'Lovely textures and color!!', '2013-01-06 09:42:04.000000', NULL, 1),
(6950347, 1045942, 64446, '<td valign="top">wonderful framing!</td>', 'wonderful framing!', '2013-01-06 09:43:18.000000', NULL, 1),
(6950348, 1047336, 100393, '<td valign="top">I''m going through the entries, stopping at those images I feel have had the benefit of an unconventional eye and dwelling a little longer to try to see and appreciate what you saw. This is one of those images. <br/> <br/>Positives: Love how you have thrown away the colour option to give us something rather deeper - a concentration of form and light and perspective. What make this is the way the whole thing is compositionally balanced and how you have avoided the ends of the grey scale range.<br/> <br/>Critical stuff: Nope<br/> <br/>Overall: Characterised by the subtlety of a master at work.</td>', 'I''m going through the entries, stopping at those images I feel have had the benefit of an unconventional eye and dwelling a little longer to try to see and appreciate what you saw. This is one of those images.  Positives: Love how you have thrown away the colour option to give us something rather deeper - a concentration of form and light and perspective. What make this is the way the whole thing is compositionally balanced and how you have avoided the ends of the grey scale range. Critical stuff: Nope Overall: Characterised by the subtlety of a master at work.', '2013-01-06 09:43:58.000000', NULL, 1),
(6950349, 1047374, 100393, '<td valign="top">I''m going through the entries, stopping at those images I feel have had the benefit of an unconventional eye and dwelling a little longer to try to see and appreciate what you saw. This is one of those images. <br/> <br/>Positives: Goodness, this is brave. Blur, grain, in-your-face coloration, ambiguity of subject - all ensuring that you put distance between yourself and the admirers of eye-candy-cliche. I like it (despite liking a bit of eye candy myself), I like how it engages the imagination - for me, this is definitely neurological in its suggestion.<br/> <br/>Critical stuff: Given the joy of engaging the imagination - I wish you had left us with a less steering title.<br/> <br/>Overall: Powerful.</td>', 'I''m going through the entries, stopping at those images I feel have had the benefit of an unconventional eye and dwelling a little longer to try to see and appreciate what you saw. This is one of those images.  Positives: Goodness, this is brave. Blur, grain, in-your-face coloration, ambiguity of subject - all ensuring that you put distance between yourself and the admirers of eye-candy-cliche. I like it (despite liking a bit of eye candy myself), I like how it engages the imagination - for me, this is definitely neurological in its suggestion. Critical stuff: Given the joy of engaging the imagination - I wish you had left us with a less steering title. Overall: Powerful.', '2013-01-06 09:48:38.000000', NULL, 1),
(6950350, 1047360, 100393, '<td valign="top">I''m going through the entries, stopping at those images I feel have had the benefit of an unconventional eye and dwelling a little longer to try to see and appreciate what you saw. This is one of those images. <br/> <br/>Positives: A country scene turned a little dark - I like that; it feels cinematic; we wait for the camera to pan upwards and sweep leftwards in a curve. The tones are really good too - emphasising the oppressive feel of the subject matter. The depth of field is perfect too - the house soft and looming...<br/> <br/>Critical stuff: Nope.<br/> <br/>Overall: Very well made.</td>', 'I''m going through the entries, stopping at those images I feel have had the benefit of an unconventional eye and dwelling a little longer to try to see and appreciate what you saw. This is one of those images.  Positives: A country scene turned a little dark - I like that; it feels cinematic; we wait for the camera to pan upwards and sweep leftwards in a curve. The tones are really good too - emphasising the oppressive feel of the subject matter. The depth of field is perfect too - the house soft and looming... Critical stuff: Nope. Overall: Very well made.', '2013-01-06 09:51:10.000000', NULL, 1),
